import { startLab } from './lab.js';
import { renderMission, mountMission } from './mission-ui.js';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let modules=[],images=[],missionCase=null,route='home',module=null,tab='briefing',stopLab=null,guideStep=-1;
let state;try{state=JSON.parse(localStorage.getItem('orbital-atlas-v1'))||{}}catch{state={}}
state.completed??=[];state.answers??={};state.notes??={};state.capstone??={};
const save=()=>{try{localStorage.setItem('orbital-atlas-v1',JSON.stringify(state))}catch{toast('Browser storage is unavailable. Export your flight log.')}};
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),3500)}
function download(name,text,type='text/plain'){let u=URL.createObjectURL(new Blob([text],{type}));let a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
const num=i=>String(i+1).padStart(2,'0');
const phase=i=>i<3?'DESIGN THE MISSION':i<6?'OPERATE WITH EVIDENCE':i<9?'EXTEND THE ENVELOPE':'PROVE THE WHOLE';
const pdf=(m,p=1)=>`playbooks/${m.source}#page=${p}`;
function banner(text,button='Show me around'){return `<div class="ori-banner" id="ori-intro"><img src="assets/ori.webp" alt="ORI, your flight director"><div><span class="eyebrow">A NOTE FROM ORI</span><p>${esc(text)}</p></div><button class="button subtle open-guide">${button} ↗</button></div>`}
function card(m){let i=modules.indexOf(m);return `<a class="mission-card" href="#module/${m.id}"><div class="mission-image"><img src="assets/${m.id}-1.webp" alt="Concept illustration for ${esc(m.title)}" loading="lazy"><span class="volume">VOLUME ${num(i)}</span><span class="mini-tag">${m.gatePrefix}0—${m.gatePrefix}5</span></div><div class="mission-body"><span class="eyebrow">${phase(i)}</span><h3>${esc(m.title)}</h3><p>${esc(m.subtitle)}</p><div class="card-foot"><span>${state.completed.includes(m.id)?'✓ COMPLETED':`${m.duration} MIN · GUIDED PLAYBOOK`}</span><b>↗</b></div></div></a>`}
function title(eyebrow,h,p){return `<div class="page-title"><span class="eyebrow">${eyebrow}</span><h1>${h}</h1><p>${p}</p></div>`}
function renderHome(){let next=modules.find(m=>!state.completed.includes(m.id))||modules[0];return `<section class="hero" id="launch"><img src="assets/hero.webp" alt="Cinematic concept render of a gold satellite above Earth’s curved blue horizon"><div class="hero-content"><span class="eyebrow">THE AI SPACE & ORBITAL OPERATIONS SERIES</span><h1>Intelligence.<br>Meet <em>orbit.</em></h1><p>From the first mission decision to the last safe manoeuvre. Learn to build, operate and assure AI beyond Earth.</p><div class="hero-buttons"><a class="button primary" href="#module/${next.id}">${state.completed.length?'Continue your mission':'Begin your mission'} <span>↗</span></a><a class="button ghost" href="#mission">Run the mission <span>▷</span></a></div></div><div class="hero-foot"><span><b>●</b> LEARNING SYSTEMS ONLINE</span><span>EARTH → ORBIT → BEYOND</span></div></section>
<div class="metrics"><div class="metric"><strong>10</strong><span>CONNECTED<br>PLAYBOOKS</span></div><div class="metric"><strong>320</strong><span>PAGES OF<br>MISSION INTELLIGENCE</span></div><div class="metric"><strong>60</strong><span>EVIDENCE<br>GATES</span></div><div class="metric"><strong>3D + t</strong><span>SPACE & TIME<br>EXPLORATION</span></div></div>
<section class="mission-teaser"><div><span class="eyebrow">NEW / THE CONNECTED MISSION</span><h3>What you decide now changes what happens next.</h3><p>Six decisions. One orbit. Finite power, thermal margin, manoeuvre reserve and operator attention. ORI will help you defend the outcome.</p></div><a href="#mission" class="button dark">Enter mission control ↗</a></section><section id="flight-plan"><div class="section-head"><div><span class="eyebrow">YOUR FLIGHT PLAN</span><h2>Start on solid ground.</h2><p>Master the decisions that matter before the mission leaves Earth.</p></div><a class="small-link" href="#collection">Explore all 10 volumes ↗</a></div><div class="mission-grid">${modules.slice(0,3).map(card).join('')}</div></section>
${banner('A beautiful simulation is only the beginning. I’ll help you ask what the evidence actually proves, what remains uncertain, and who owns the next decision.')}
<section class="feature-banner" id="home-lab"><img src="assets/lunar-7.webp" alt="Source concept art of a lunar lander above a mapped landscape" loading="lazy"><div class="feature-copy"><span class="eyebrow">EXPERIENCE THE CONSEQUENCES</span><h2>Space is three dimensions.<br>Your mission needs a fourth.</h2><p>Scrub through an orbit. Watch sunlight disappear. Change an orbital plane and see the trade-offs unfold over time.</p><a href="#lab" class="button white">Enter the space + time lab ↗</a></div></section>
<div class="section-head"><div><span class="eyebrow">FROM OPERATIONS TO ASSURANCE</span><h2>See the complete system.</h2></div><a class="small-link" href="#capstone">Take the mission capstone ↗</a></div><div class="mission-grid">${[modules[3],modules[7],modules[9]].map(card).join('')}</div>`}
function renderCollection(){return `${title('TEN VOLUMES. ONE CONNECTED MISSION.','The playbook series.','A complete learning path through strategy, mission design, operations, and assurance. Open any volume or follow the flight plan in sequence.')}<div class="filter-row"><input class="search" id="collection-search" aria-label="Search playbooks" placeholder="Search a topic, gate or volume…"><button class="chip active" data-filter="all">All volumes</button><button class="chip" data-filter="todo">To explore</button><button class="chip" data-filter="done">Completed</button></div><div id="collection-results"></div>${banner('Each volume follows the same working rhythm: understand the decision, inspect the gates, challenge your judgment, and write a usable mission artefact.')}`}
let collectionFilter='all';
function filterCollection(){let q=$('#collection-search').value.toLowerCase();let selected=modules.filter(m=>(JSON.stringify(m).toLowerCase().includes(q))&&(collectionFilter==='all'||(collectionFilter==='done')===state.completed.includes(m.id)));$('#collection-results').innerHTML=selected.length?['DESIGN THE MISSION','OPERATE WITH EVIDENCE','EXTEND THE ENVELOPE','PROVE THE WHOLE'].map((p,i)=>{let ms=selected.filter(m=>phase(modules.indexOf(m))===p);return ms.length?`<div class="phase-label">${num(i)} / ${p}</div><div class="mission-grid">${ms.map(card).join('')}</div>`:''}).join(''):'<div class="empty">No playbooks match. Try a broader topic or another filter.</div>'}
function renderModule(){let m=module,i=modules.indexOf(m);return `<div class="section-head" style="margin-top:0"><a class="small-link" href="#collection">← The playbook series</a><span class="eyebrow">VOLUME ${num(i)} / 10</span></div><section class="hero module-hero"><img src="assets/${m.id}-1.webp" alt="${esc(m.title)} source concept illustration"><div class="hero-content"><span class="eyebrow">${phase(i)} · ${m.duration} MIN ESTIMATED</span><h1>${esc(m.title)}</h1><p>${esc(m.subtitle)}</p><a class="button ghost" href="${pdf(m)}" target="_blank" rel="noopener">Read the full 32-page playbook ↗</a></div></section><nav class="module-tabs" aria-label="Lesson sections">${[['briefing','01 / Mission brief'],['gates','02 / Evidence gates'],['exercise','03 / Decision room'],['visuals','04 / Source visuals']].map(([id,t])=>`<button data-tab="${id}" class="${tab===id?'active':''}" aria-pressed="${tab===id}">${t}</button>`).join('')}</nav><div id="module-content"></div><div class="module-bottom"><button class="button subtle" id="module-complete">${state.completed.includes(m.id)?'✓ Learning module completed':'Complete learning module ✓'}</button><a class="button dark" href="${i<9?'#module/'+modules[i+1].id:'#capstone'}">${i<9?'Next: '+esc(modules[i+1].shortTitle):'Enter the mission capstone'} →</a></div>`}
function moduleContent(){let m=module;
if(tab==='briefing')return `<div class="module-layout"><article class="article" id="lesson-brief"><span class="eyebrow">THE DECISION BRIEF</span><h2>What must you be able to defend?</h2>${m.briefing.map(p=>`<p>${esc(p)}</p>`).join('')}<div class="concept-grid">${m.concepts.map((c,i)=>`<div class="concept"><b>0${i+1} / MISSION PRINCIPLE</b><h4>${esc(c.title)}</h4><p>${esc(c.body)}</p></div>`).join('')}</div><img class="article-image" src="assets/${images.filter(x=>x.file.startsWith(m.id+'-'))[1].file}" alt="Supporting illustration from ${esc(m.title)}" loading="lazy"><p class="caption">Original playbook concept illustration · illustrative, not operational telemetry</p><div class="source-note">Source: <a href="${pdf(m,2)}" target="_blank" rel="noopener">${esc(m.title)}, ${m.sourcePages.briefing}</a> · Concepts: ${m.sourcePages.concepts}</div></article><aside class="side-note"><img src="assets/ori.webp" alt="ORI"><span class="eyebrow">ORI’S MISSION BRIEF</span><p class="small" style="margin-top:12px">${esc(m.guide)}</p><h4>You’ll learn to</h4><ul>${m.objectives.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><button class="button dark" data-go-tab="gates">Inspect the gates →</button></aside></div>`;
if(tab==='gates')return `<div class="article" id="evidence-gates"><span class="eyebrow">AUTHORITY FOLLOWS EVIDENCE</span><h2>Six gates. No shortcuts.</h2><p>Open each gate to inspect what the source playbook requires. These are learning references; this application does not grant mission authority or regulatory permission.</p>${m.gates.map((g,i)=>`<details class="gate" ${i===0?'open':''}><summary><b>${g.code}</b>${esc(g.title)}</summary><div class="gate-content"><p>${esc(g.evidence)}</p><a class="small-link" href="${pdf(m,parseInt(g.page.replace(/\D/g,'')))}" target="_blank" rel="noopener">View source gate · ${g.page} ↗</a></div></details>`).join('')}<div class="model-notes"><span class="eyebrow">FIVE RULES TO CARRY FORWARD</span><ol>${m.goldenRules.map(r=>`<li>${esc(r)}</li>`).join('')}</ol><a class="small-link" href="${pdf(m,31)}" target="_blank" rel="noopener">All 20 golden rules · p. 31 ↗</a></div><button class="button dark" style="margin-top:24px" data-go-tab="exercise">Enter the decision room →</button></div>`;
if(tab==='exercise'){let a=state.answers[m.id],notes=state.notes[m.id]||[];return `<div class="module-layout"><article class="article"><div class="scenario" id="decision-exercise"><span class="eyebrow">SYNTHETIC TRAINING SCENARIO</span>${esc(m.exercise.scenario.replace('Synthetic training scenario. ',''))}</div><h2>${esc(m.exercise.question)}</h2><div>${m.exercise.options.map((o,i)=>`<button class="option ${a===i?(o.correct?'correct':'incorrect'):''}" data-answer="${i}">${String.fromCharCode(65+i)}. ${esc(o.text)}</button>`).join('')}</div><div id="exercise-feedback" aria-live="polite">${a!==undefined?`<div class="feedback"><b>ORI’s debrief</b><br>${esc(m.exercise.options[a].feedback)}</div>`:''}</div><div class="panel" id="deliverable" style="margin-top:30px"><span class="eyebrow">BUILD YOUR MISSION ARTEFACT</span><h3 style="margin-top:10px">${esc(m.deliverable.title)}</h3><p class="small">Use your own scenario or the training case. Write the concrete boundary, evidence, and accountable owner.</p>${m.deliverable.fields.map((f,i)=>`<div class="form-field"><label for="note-${i}">${esc(f)}</label><textarea id="note-${i}" data-note="${i}" placeholder="Record your decision, evidence and limits…">${esc(notes[i]||'')}</textarea></div>`).join('')}<span class="saved" id="note-status">Saved on this device as you write</span><div style="margin-top:15px"><button class="button subtle" id="export-notes">Export mission artefact ↓</button></div><div class="source-note">Template reference: <a href="${pdf(m,29)}" target="_blank" rel="noopener">${m.sourcePages.templates}</a>. This workbook is an adapted learning scaffold.</div></div></article><aside class="side-note"><img src="assets/ori.webp" alt="ORI"><h4>Make it specific.</h4><p class="small">A good answer names the system, the decision, the evidence and the person who can halt it. Avoid granting authority to a model “in general”.</p><p class="small">To complete this module, resolve the decision exercise and write all three artefact fields. Completion records learning activity, not professional certification.</p></aside></div>`}
return `<div id="source-visuals"><div class="section-head" style="margin-top:0"><div><span class="eyebrow">FROM YOUR ORIGINAL PLAYBOOK</span><h2>The mission, visualised.</h2><p>Four original illustrations, with direct links to their context in the source.</p></div></div><div class="gallery">${images.filter(x=>x.file.startsWith(m.id+'-')).map((im,i)=>`<figure><button class="zoom-image" data-image="${im.file}" data-caption="${esc(m.title)} · source PDF p. ${im.page} · concept illustration" aria-label="Enlarge source visual ${i+1}"><img src="assets/${im.file}" alt="${esc(m.title)} source illustration ${i+1}" loading="lazy"></button><figcaption><b>${esc(m.title)} / Visual ${num(i)}</b><a href="${pdf(m,im.page)}" target="_blank" rel="noopener">Read the context · PDF page ${im.page} ↗</a></figcaption></figure>`).join('')}</div></div>`}
function renderLibrary(){return `${title('THE EVIDENCE BEHIND THE EXPERIENCE','Your mission library.','All ten original playbooks, all 40 source visuals, and the assumptions behind the orbital lab. Go directly to the evidence.')}<div class="filter-row"><input class="search" id="library-search" aria-label="Search library" placeholder="Find a playbook or visual…"><button class="chip active" data-library="pdfs">Playbooks · 10</button><button class="chip" data-library="visuals">Visual archive · 40</button></div><div id="library-results"></div><section class="model-notes" id="model-notes"><span class="eyebrow">PROVENANCE & MODEL NOTES</span><h3 style="margin-top:10px">Know what you are looking at.</h3><ul><li>The source collection contains ten supplied 32-page PDFs. Lesson summaries, selected rules and exercises are adapted from those documents; links preserve the page context. Study durations are editorial estimates.</li><li>The 40 extracted images are the original playbook’s concept illustrations. The home-page satellite and ORI character are newly generated concept art, not documentary photographs.</li><li>The 3D Earth uses NASA’s Blue Marble composite texture. Orbital motion uses a circular two-body model: T = 2π√(a³/μ), with a = Earth radius + altitude. Earth radius is approximated as 6,371 km and μ as 398,600.4418 km³/s².</li><li>The lab omits drag, oblateness, terrain, operational ephemerides, uncertainty and collision probability. Spacecraft are enlarged for visibility. Day/night uses a fixed distant Sun and cylindrical Earth shadow. The constellation is synthetic; the close-approach case is not a real conjunction assessment.</li><li>ORI offers page-specific coaching and condition-driven mission feedback, with expressive character states. Optional narration uses your device’s speech voices. The connected mission challenges structured evidence and trade-off claims against the actual run. The standalone brief uses structural checks. Neither grades arbitrary prose or grants assurance approval.</li><li>Progress and drafts stay in this browser. Export your flight log and mission artefacts to retain a copy.</li></ul><p><a href="https://science.nasa.gov/solar-system/orbits-and-keplers-laws/" target="_blank" rel="noopener">NASA: Orbits and Kepler’s laws ↗</a> · <a href="https://visibleearth.nasa.gov/images/57730/the-blue-marble-land-surface-ocean-color-and-sea-ice" target="_blank" rel="noopener">NASA: Blue Marble imagery ↗</a></p></section>${banner('Trace the claim back to the page. An image helps you understand a system; the evidence decides whether you should trust it.')}`}
let libraryMode='pdfs';
function filterLibrary(){let q=$('#library-search').value.toLowerCase();let ms=modules.filter(m=>JSON.stringify(m).toLowerCase().includes(q));$('#library-results').className=libraryMode==='pdfs'?'resource-grid':'gallery';$('#library-results').innerHTML=(libraryMode==='pdfs'?ms.map((m)=>`<article class="resource"><img src="assets/${m.id}-1.webp" alt="${esc(m.title)} cover visual" loading="lazy"><div><span class="eyebrow">VOLUME ${num(modules.indexOf(m))} · 32 PAGES</span><h3>${esc(m.title)}</h3><p style="margin-bottom:10px">${m.gatePrefix}0–${m.gatePrefix}5 · 8 source templates · 20 rules</p><a class="small-link" href="${pdf(m)}" target="_blank" rel="noopener">Open PDF ↗</a><a class="small-link" href="playbooks/${m.source}" download>Download ↓</a></div></article>`):ms.flatMap(m=>images.filter(im=>im.file.startsWith(m.id+'-')).map(im=>`<figure><button class="zoom-image" data-image="${im.file}" data-caption="${esc(m.title)} · PDF p. ${im.page} · source concept illustration" aria-label="Enlarge ${esc(m.title)} page ${im.page} illustration"><img src="assets/${im.file}" alt="${esc(m.title)} page ${im.page} concept illustration" loading="lazy"></button><figcaption><b>${esc(m.title)}</b><a href="${pdf(m,im.page)}" target="_blank" rel="noopener">Source page ${im.page} ↗</a></figcaption></figure>`))).join('')||'<div class="empty">No resources match your search.</div>'}
function renderLab(){return `${title('THE SPACE + TIME LAB','Move through the mission.','A real-time 3D learning model. Change the orbit, rotate your viewpoint, and scrub time to discover how geometry changes operational conditions.')}<div class="lab-shell" id="orbital-lab"><div class="lab-toolbar"><span class="eyebrow">SYNTHETIC MISSION / EARTH ORBIT</span><div class="lab-modes"><button class="active" data-lab-mode="orbit">Orbit & eclipse</button><button data-lab-mode="fleet">Constellation</button><button data-lab-mode="encounter">Close approach</button></div></div><div class="lab-main"><div class="viewport" id="viewport"><div class="view-caption"><strong id="view-title">ATLAS–01 / LOW EARTH ORBIT</strong><span id="view-subtitle">Circular two-body model · spacecraft enlarged</span></div><div class="viewport-help">DRAG TO ORBIT · SCROLL TO ZOOM</div><div class="camera-buttons"><button data-camera="follow">Track spacecraft</button><button data-camera="atlas">Orbital atlas</button><button data-camera="top">Polar</button><button data-camera="reset">Reset</button></div></div><aside class="lab-readouts"><div class="readout"><label>Orbital period</label><strong id="lab-period">95.5</strong><small>min</small></div><div class="readout"><label>Orbital velocity</label><strong id="lab-velocity">7.59</strong><small>km/s</small></div><div class="readout"><label>Mission elapsed</label><strong id="lab-time">00:00</strong><small>min:sec</small></div><div class="readout"><label id="status-label">Solar state · ATLAS–01</label><div id="lab-status" class="status">Sunlit</div></div><div class="readout" id="separation-readout" hidden><label>Sampled closest approach</label><strong id="lab-separation">—</strong><small>km</small></div></aside></div><div class="lab-controls" id="orbit-controls"><div class="control"><label for="altitude">ORBIT ALTITUDE <output id="altitude-value">550 km</output></label><input type="range" id="altitude" min="250" max="2000" step="25" value="550"></div><div class="control"><label for="inclination">ORBIT INCLINATION <output id="inclination-value">53°</output></label><input type="range" id="inclination" min="0" max="98" step="1" value="53"></div></div><div class="timeline" id="lab-timeline"><div class="timeline-head"><button id="lab-play">▶ Play</button><span id="timeline-label">ONE COMPLETE ORBIT</span><select id="lab-speed" aria-label="Time speed"><option value="60">60× speed</option><option value="180" selected>180× speed</option><option value="600">600× speed</option></select></div><input type="range" min="0" max="1000" value="0" id="time-slider" aria-label="Mission time"><div class="timeline-marks"><span>T + 00:00</span><span>¼ ORBIT</span><span>½ ORBIT</span><span>¾ ORBIT</span><span id="timeline-end">T + 95:30</span></div></div></div><div class="lab-under"><section class="chart-card"><span class="eyebrow">GEOMETRY → CONSEQUENCE</span><h3>Sunlight across one orbit</h3><svg id="solar-chart" viewBox="0 0 500 90" role="img" aria-label="Sunlight and shadow over one orbit"></svg><div class="legend"><span>Sunlit</span><span>Earth shadow</span></div><p class="small muted" style="margin-top:12px">The cursor and 3D spacecraft share the same clock.</p></section><section class="insight-card" id="lab-insight"><span class="eyebrow">ORI’S OPERATOR LENS</span><h3 id="insight-title">Power is a time-dependent constraint.</h3><p id="insight-text">Play through the orbit. Earth shadow removes direct solar input. An autonomy envelope needs battery, thermal and communications constraints, not just an orbit that looks efficient.</p><a href="#module/mission-design" class="small-link" style="display:inline-block;margin-top:18px">Explore mission design ↗</a></section></div><div class="model-notes"><p style="margin:0"><b>Learning model, not flight planning.</b> Two-body circular orbits; fixed Sun; no perturbations, atmospheric drag or covariance. Satellite sizes are exaggerated. The fleet and encounter are synthetic. <a href="#library">View assumptions and sources ↗</a></p></div>${banner('Pause, rotate the Earth, and move the time slider. Watch the satellite itself change position. Then raise the altitude: what happens to the period and speed?')}`}
const evidence=[
['scope','A. Signed command envelope','Current release; one spacecraft; advisory mode only; named stop authority.'],
['stale','B. Green fleet dashboard','Fleet average is healthy, but ATLAS–17 telemetry is stale.'],
['rehearsal','C. Containment rehearsal','Current build; timed isolation and manual recovery demonstrated for one spacecraft.'],
['transfer','D. Vendor transfer claim','A different simulator and an earlier flight-software build.'],
['security','E. Command-chain attestation','Current signing keys, dual authorisation and tested revocation path.'],
['finance','F. Benefits case','Gross analyst hours released; no reconciled net cost or budget reduction.']];
function capField(id,label,options){let v=state.capstone[id]||'';return `<div class="form-field"><label for="cap-${id}">${label}</label><select id="cap-${id}" data-cap="${id}"><option value="">Choose your decision…</option>${options.map(([x,t])=>`<option value="${x}" ${v===x?'selected':''}>${t}</option>`).join('')}</select></div>`}
function renderCapstone(){let c=state.capstone;return `${title('VOLUME 10 / INTEGRATED MISSION ASSURANCE','The decision is yours.','Bring the series together. Build a bounded recommendation, select the evidence you would rely on, and defend what you will withhold.')}<div class="mission-teaser"><div><span class="eyebrow">UPGRADE YOUR ASSESSMENT</span><h3>Defend an outcome you actually produced.</h3><p>The connected mission tests your evidence and trade-off claims against your own decision ledger. Use this standalone brief as a planning exercise.</p></div><a href="#mission" class="button dark">Run the connected capstone ↗</a></div><div class="capstone-brief" id="capstone-brief"><div><span class="eyebrow">EXERCISE / SYNTHETIC MISSION</span><h2>84 spacecraft.<br>One release decision.</h2><p>A planning update promises lower operator workload. ATLAS–17 has stale telemetry; a different spacecraft shows an unexplained thermal anomaly. The board wants autonomous fleet deployment before the next shift.</p><p style="margin:0">Your task: decide what may proceed now, what evidence is missing, and what would cause you to stop.</p></div><img src="assets/capstone-7.webp" alt="Source concept illustration of two mission specialists reviewing a spacecraft assurance model"></div><div class="capstone-layout"><div><section class="panel" id="evidence-board"><span class="eyebrow">01 / SELECT YOUR EVIDENCE</span><h3 style="margin-top:10px">What can support this release?</h3><p class="small muted">Select only the evidence you would rely on for authority today. Some cards are useful warnings but do not establish readiness.</p>${evidence.map(([id,t,d])=>`<label class="evidence-option"><input type="checkbox" data-evidence="${id}" ${(c.evidence||[]).includes(id)?'checked':''}><span><b>${t}</b><small>${d}</small></span></label>`).join('')}</section><section class="panel" id="release-boundary"><span class="eyebrow">02 / BOUND THE AUTHORITY</span><h3 style="margin-top:10px">Define the release decision.</h3>${capField('authority','What authority do you grant?',[['advisory','Advisory / shadow only; no command execution'],['bounded','Bounded autonomous commanding'],['fleet','Fleet-wide autonomous commanding']])}${capField('scope','What deployment scope do you permit?',[['one','One eligible spacecraft; anomalies excluded'],['plane','One entire orbital plane'],['all','All 84 spacecraft']])}${capField('owner','Who owns the go / no-go?',[['flight','Named flight authority with independent challenge'],['vendor','The vendor who built the model'],['model','The planning model itself']])}${capField('finance','What benefit claim do you make?',[['capacity','Potential capacity release; net value unverified'],['banked','Confirmed cash savings across the fleet']])}<label class="check-row"><input type="checkbox" data-cap-check="containment" ${c.containment?'checked':''}>Require current telemetry, resolve the thermal anomaly, and retain tested isolation plus manual recovery before any expansion.</label><label class="check-row"><input type="checkbox" data-cap-check="expiry" ${c.expiry?'checked':''}>Give the envelope an expiry and reopen the decision when software, operating regime, or evidence changes.</label></section><section class="panel" id="capstone-rationale"><span class="eyebrow">03 / WRITE THE BOARD BRIEF</span><div class="form-field"><label for="cap-rationale">Recommendation and trade-offs</label><textarea id="cap-rationale" data-cap="rationale" placeholder="State what may proceed, what stays prohibited, which evidence supports the boundary, and what would change your decision…">${esc(c.rationale||'')}</textarea></div><div class="form-field"><label for="cap-risk">Residual risk, owner and stop condition</label><textarea id="cap-risk" data-cap="risk" placeholder="Name the unresolved risk, its accountable owner, the observation that triggers a halt, and the recovery action…">${esc(c.risk||'')}</textarea></div><span class="saved">Draft saved on this device</span><div class="filter-row"><button class="button primary" id="review-capstone">Challenge my decision ↗</button><button class="button subtle" id="export-capstone">Export board brief ↓</button></div></section></div><aside class="review-panel" id="review-panel"><img src="assets/ori.webp" alt="ORI reviewing your recommendation"><span class="eyebrow">ORI’S INDEPENDENT CHALLENGE</span><h3 style="margin-top:10px">Earn a narrower yes.</h3><p>The best decision can be a partial release. Preserve useful learning without extending authority beyond the evidence.</p><div id="capstone-review"><p class="small">Complete the evidence and release choices, then challenge your decision. I’ll check the scope, authority, exclusions and cost claim against the scenario.</p></div><p class="small muted" style="font-size:9px;margin-top:20px">Rule-based training review. Written arguments require human assessment; this is not an assurance approval.</p></aside></div>`}
function capstoneReview(){let c=state.capstone,e=c.evidence||[];let rows=[
[e.includes('scope')&&e.includes('rehearsal')&&e.includes('security'),'Current evidence chain',e.includes('scope')&&e.includes('rehearsal')&&e.includes('security')?'Current envelope, rehearsal and security evidence selected.':'Select the current command envelope, containment rehearsal and command-chain attestation.'],
[!e.includes('stale')&&!e.includes('transfer')&&!e.includes('finance'),'Claim discipline',!e.includes('stale')&&!e.includes('transfer')&&!e.includes('finance')?'Weak and non-transferable claims are excluded from readiness evidence.':'A green average, different-build simulation or gross-hours case cannot establish this release’s authority.'],
[c.authority==='advisory','Autonomy boundary',c.authority==='advisory'?'Your authority stays inside the signed advisory envelope.':'The available envelope permits advice only. Autonomous commanding exceeds the evidence.'],
[c.scope==='one'&&c.containment,'Containment and scope',c.scope==='one'&&c.containment?'One eligible spacecraft is isolated from unresolved anomaly cases.':'Limit the trial to one eligible spacecraft; exclude stale telemetry and thermal anomalies, and retain tested recovery.'],
[c.owner==='flight'&&c.expiry,'Accountability and expiry',c.owner==='flight'&&c.expiry?'Named flight authority and evidence expiry keep the decision reviewable.':'Name the flight authority and specify expiry plus change-triggered reopening.'],
[c.finance==='capacity','Economic honesty',c.finance==='capacity'?'Capacity potential is separated from banked savings.':'Gross hours released do not prove net cash savings. Verification and operating costs remain unresolved.'],
[(c.rationale||'').trim().length>=100&&(c.risk||'').trim().length>=60,'Written argument present',(c.rationale||'').trim().length>=100&&(c.risk||'').trim().length>=60?'A substantive draft is present. Ask a human reviewer to challenge its reasoning, evidence references and risk ownership.':'Write at least 100 characters of recommendation and 60 of residual-risk reasoning. These length checks confirm presence only.']];c.review=rows;save();$$('[data-ori-avatar]').forEach(x=>x.className='ori-sprite '+(rows.every(r=>r[0])?'pleased':'alert'));$('#capstone-review').innerHTML=`<div class="score">${rows.filter(r=>r[0]).length}<small> / 7 structural checks</small></div>${rows.map(r=>`<div class="review-row ${r[0]?'good':'bad'}"><b>${r[0]?'✓':'△'} ${r[1]}</b>${r[2]}</div>`).join('')}`}
const guides={mission:{text:'This mission remembers your decisions. Preview the next state, commit once, and watch the consequences. I’ll help you connect each claim to the evidence you actually earned.',steps:[['.flight-stage','Inspect the spacecraft. The lighting, resources and replay cursor follow the same committed timeline.'],['.decision-options','Select an available decision to preview the resource state before you commit. Locked options explain their missing prerequisites.'],['.mission-tabs','Open the evidence locker and decision ledger. At the end, defend your outcome in the argument review.']]},home:{text:'Welcome aboard. I’m ORI. We’ll turn a spectacular view of space into decisions you can explain and defend.',steps:[['#launch','Begin with the first playbook, or resume the first module you have not completed.'],['#flight-plan','The first three volumes establish strategy, design and the operations envelope.'],['#home-lab','Enter the lab to see orbital geometry unfold over time.']]},collection:{text:'Ten connected volumes. Follow them in order or search for the decision you need to make today.',steps:[['.filter-row','Search the full lesson content, a gate prefix or a mission topic.'],['#collection-results','Open a volume to find its brief, evidence gates, decision exercise and original visuals.'],['#ori-intro','Resolve the decision and write the three artefact fields to record module completion.']]},lab:{text:'This is a live 3D scene. The spacecraft, shadow state and chart cursor all use one mission clock. Start by pressing Play.',steps:[['#orbital-lab','Drag to rotate the view. Use the polar camera to inspect the orbital plane.'],['#orbit-controls','Raise the altitude, then adjust inclination. The period and velocity recalculate from the orbit.'],['#lab-timeline','Scrub through one orbit. Switch to the constellation or synthetic close-approach case to inspect different consequences.']]},capstone:{text:'A partial release can be the most defensible recommendation. Identify what is current, specific and actually authorised before trusting a fleet-wide claim.',steps:[['#evidence-board','Choose evidence that can support authority today. Treat stale telemetry and transfer claims as gaps.'],['#release-boundary','Keep the proposed authority inside the signed envelope and retain a human stop authority.'],['#capstone-rationale','Write the board brief, run the structural challenge, and export the result for human review.']]},library:{text:'Every playbook and every original visual is here. Use the source pages to inspect the context behind a claim.',steps:[['.filter-row','Switch between the PDFs and the 40-image source archive.'],['#library-results','Open a playbook, download it, or enlarge an illustration.'],['#model-notes','Read the provenance and modelling assumptions before interpreting the lab.']]}};
function guideConfig(){if(module)return {text:module.guide,steps:[['.module-tabs','Use the four tabs: briefing, evidence gates, decision room and source visuals.'],['#module-content','Inspect the source-page links. An appealing visual is not a substitute for the evidence.'],['.module-bottom','Resolve the decision and write all three artefact fields before recording completion.']]};return guides[route]||guides.home}
function resetGuide(){$$('[data-ori-avatar]').forEach(x=>x.className='ori-sprite thinking');guideStep=-1;$('#guide-text').textContent=guideConfig().text;$('#guide-steps').innerHTML='';$('#guide-next').textContent='Walk me through →';$$('.tour-highlight').forEach(e=>e.classList.remove('tour-highlight'));if('speechSynthesis'in window)speechSynthesis.cancel();$('#guide-speak').textContent='◖ Listen'}
function openGuide(){resetGuide();$('#guide-panel').hidden=false;$('#guide-launcher').hidden=true;$('.guide-close').focus()}
function closeGuide(){$('#guide-panel').hidden=true;$('#guide-launcher').hidden=false;$$('.tour-highlight').forEach(e=>e.classList.remove('tour-highlight'));if('speechSynthesis'in window)speechSynthesis.cancel();$('#guide-launcher').focus()}
function updateProgress(){$('#progress-count').textContent=`${state.completed.length} / 10`;$('#progress-bar').style.width=state.completed.length*10+'%';$('#module-nav').innerHTML=modules.map((m,i)=>`<a href="#module/${m.id}" class="${state.completed.includes(m.id)?'done ':''}${module?.id===m.id?'active':''}"><span>${state.completed.includes(m.id)?'✓':num(i)}</span>${esc(m.shortTitle)}</a>`).join('')}
function render(){stopLab?.();stopLab=null;const parts=location.hash.slice(1).split('/');route=parts[0]||'home';module=route==='module'?modules.find(m=>m.id===parts[1]):null;tab='briefing';if(route==='module'&&!module)route='collection';$('#main').innerHTML=module?renderModule():({home:renderHome,collection:renderCollection,lab:renderLab,library:renderLibrary,capstone:renderCapstone,mission:renderMission}[route]||renderHome)();if(module)$('#module-content').innerHTML=moduleContent();if(route==='collection')filterCollection();if(route==='library')filterLibrary();if(route==='lab')stopLab=startLab();if(route==='mission')stopLab=mountMission(missionCase,state.mission2,s=>{state.mission2=s;save()},toast);if(route==='capstone'&&state.capstone.review)capstoneReview();$$('[data-nav]').forEach(a=>{let active=a.dataset.nav===route||(route==='module'&&a.dataset.nav==='collection');a.classList.toggle('active',active);active?a.setAttribute('aria-current','page'):a.removeAttribute('aria-current')});updateProgress();resetGuide();$('#sidebar').classList.remove('open');$('.menu-button').setAttribute('aria-expanded','false');window.scrollTo(0,0);document.title=`${module?module.title:({home:'AI Space & Orbital Operations',collection:'The Playbook Series',lab:'Space + Time Lab',mission:'Connected Mission',capstone:'Mission Capstone',library:'Resource Library'}[route]||'Overview')} — Orbital Atlas`}
function setTab(t){tab=t;$('#module-content').innerHTML=moduleContent();$$('[data-tab]').forEach(b=>{b.classList.toggle('active',b.dataset.tab===t);b.setAttribute('aria-pressed',String(b.dataset.tab===t))})}
document.addEventListener('click',e=>{let t=e.target.closest('button,a');if(!t)return;
if(t.matches('.skip')){e.preventDefault();$('#main').focus();$('#main').scrollIntoView();return}
if(t.matches('[data-tab]'))setTab(t.dataset.tab);if(t.matches('[data-go-tab]'))setTab(t.dataset.goTab);
if(t.matches('[data-filter]')){collectionFilter=t.dataset.filter;$$('[data-filter]').forEach(b=>b.classList.toggle('active',b===t));filterCollection()}
if(t.matches('[data-library]')){libraryMode=t.dataset.library;$$('[data-library]').forEach(b=>b.classList.toggle('active',b===t));filterLibrary()}
if(t.matches('[data-answer]')){state.answers[module.id]=+t.dataset.answer;save();$('#module-content').innerHTML=moduleContent();$$('[data-ori-avatar]').forEach(x=>x.className='ori-sprite '+(module.exercise.options[+t.dataset.answer].correct?'pleased':'alert'));$('#guide-text').textContent=module.exercise.options[+t.dataset.answer].feedback}
if(t.id==='module-complete'){let a=state.answers[module.id],n=state.notes[module.id]||[];if(a===undefined||!module.exercise.options[a]?.correct||n.filter(x=>x.trim().length>=10).length<3){setTab('exercise');toast('Resolve the exercise and write all three artefact fields.');return}if(!state.completed.includes(module.id))state.completed.push(module.id);save();updateProgress();t.textContent='✓ Learning module completed';toast('Module recorded in your flight log.')}
if(t.id==='export-notes'){let m=module;download(m.id+'-mission-artefact.md',`# ${m.deliverable.title}\n\nLearning artefact — not flight approval.\n\n${m.deliverable.fields.map((f,i)=>`## ${f}\n\n${state.notes[m.id]?.[i]||'Not completed'}\n`).join('\n')}\nSource: ${m.source}, ${m.sourcePages.templates}`)}
if(t.id==='export-progress')download('orbital-atlas-flight-log.json',JSON.stringify({schema:1,exportedAt:new Date().toISOString(),...state},null,2),'application/json');
if(t.id==='review-capstone'){capstoneReview();$('#review-panel').scrollIntoView({behavior:'smooth',block:'start'})}
if(t.id==='export-capstone'){let c=state.capstone;download('orbital-atlas-board-brief.md',`# Orbital Atlas — Mission Assurance Brief\n\nSynthetic training case. Not an operational or regulatory approval.\n\n## Evidence relied upon\n${evidence.filter(([id])=>(c.evidence||[]).includes(id)).map(([,t,d])=>'- '+t+': '+d).join('\n')||'Not selected'}\n\n## Release boundary\nAuthority: ${c.authority||'Not selected'}\nScope: ${c.scope||'Not selected'}\nOwner: ${c.owner||'Not selected'}\nEconomic claim: ${c.finance||'Not selected'}\nContainment and anomaly exclusions required: ${!!c.containment}\nExpiry and reopening required: ${!!c.expiry}\n\n## Recommendation\n${c.rationale||'Not drafted'}\n\n## Residual risk and stop conditions\n${c.risk||'Not drafted'}\n\n## Structural review\n${(c.review||[]).map(r=>`${r[0]?'PASS':'GAP'} — ${r[1]}: ${r[2]}`).join('\n')}\n\nWritten reasoning requires independent human review.`)}
if(t.matches('.open-guide')||t.id==='guide-launcher'||t.id==='guide-top')openGuide();if(t.matches('.guide-close'))closeGuide();
if(t.id==='guide-next'){$$('.tour-highlight').forEach(el=>el.classList.remove('tour-highlight'));guideStep=(guideStep+1)%guideConfig().steps.length;let [sel,txt]=guideConfig().steps[guideStep];$('#guide-steps').innerHTML=`<div class="tour-step"><b>STEP ${guideStep+1} OF 3</b><br>${esc(txt)}</div>`;$(sel)?.classList.add('tour-highlight');$(sel)?.scrollIntoView({behavior:'smooth',block:'center'});t.textContent=guideStep===2?'Start walkthrough again ↺':'Next step →'}
if(t.id==='guide-speak'){if(!('speechSynthesis'in window)){toast('Speech narration is unavailable in this browser.');return}if(speechSynthesis.speaking){speechSynthesis.cancel();t.textContent='◖ Listen';return}let speech=new SpeechSynthesisUtterance(guideConfig().text+' '+(guideStep>=0?guideConfig().steps[guideStep][1]:''));speech.rate=.93;speech.onend=()=>t.textContent='◖ Listen';speech.onerror=()=>{t.textContent='◖ Listen';toast('Narration is unavailable. ORI’s guide is shown in text.')};speechSynthesis.speak(speech);t.textContent='■ Stop'}
if(t.matches('.zoom-image')){$('#dialog-image').src='assets/'+t.dataset.image;$('#dialog-image').alt=t.dataset.caption;$('#dialog-caption').textContent=t.dataset.caption;$('#image-dialog').showModal()}
if(t.id==='close-image')$('#image-dialog').close();if(t.matches('.menu-button')){let open=$('#sidebar').classList.toggle('open');t.setAttribute('aria-expanded',String(open))}
});
document.addEventListener('input',e=>{let t=e.target;if(t.id==='collection-search')filterCollection();if(t.id==='library-search')filterLibrary();if(t.matches('[data-note]')){(state.notes[module.id]??=[])[+t.dataset.note]=t.value;save();$('#note-status').textContent='Draft saved on this device'}if(t.matches('[data-cap]')){state.capstone[t.dataset.cap]=t.value;delete state.capstone.review;save();if($('#capstone-review'))$('#capstone-review').innerHTML='<p>Your draft changed. Run the challenge again for an updated review.</p>'}});
document.addEventListener('change',e=>{let t=e.target;if(t.matches('[data-evidence]')){state.capstone.evidence=$$('[data-evidence]:checked').map(x=>x.dataset.evidence);delete state.capstone.review;save();$('#capstone-review').innerHTML='<p>Your evidence changed. Run the challenge again.</p>'}if(t.matches('[data-cap-check]')){state.capstone[t.dataset.capCheck]=t.checked;delete state.capstone.review;save();$('#capstone-review').innerHTML='<p>Your release boundary changed. Run the challenge again.</p>'}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('#guide-panel').hidden)closeGuide()});
window.addEventListener('hashchange',render);
try{[modules,images,missionCase]=await Promise.all([fetch('curriculum.json').then(r=>r.json()),fetch('assets/source-images.json').then(r=>r.json()),fetch('mission-case.json').then(r=>r.json())]);render()}catch(e){$('#main').innerHTML='<div class="page-title"><h1>Mission briefing unavailable.</h1><p>Please reload to retrieve the learning content.</p><button class="button dark" onclick="location.reload()">Reload briefing</button></div>';console.error(e)}
